arguments.argument:
with(sys_minimap_border)
{
x=view_xview+xx
y=view_yview+yy
}

x=sys_minimap_border.x-200
y=sys_minimap_border.y+360

if global._unit1.click_number>-1
{
sk_sex_set_font(1)

sk_draw_midd_text(x+10, y-25, "-배치방식-", c_purple)

if chooses=0{draw_sprite_ext(spr_o_button1, 1, x-20, y+5, 1, 1, 0, -1, 1)}
else{draw_sprite_ext(spr_o_button1, 0, x-20, y+5, 1, 1, 0, -1, 1)}

if chooses=1{draw_sprite_ext(spr_o_button1, 1, x-20, y+25, 1, 1, 0, -1, 1)}
else{draw_sprite_ext(spr_o_button1, 0, x-20, y+25, 1, 1, 0, -1, 1)}

sk_draw_kr_string(x-5, y-2, "랜덤배치", c_purple)
sk_draw_kr_string(x-5, y+18, "플레쉬배치", c_purple)

sk_sex_set_font(0)
}
